import { createCipheriv, randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, it, expect, vi } from "vitest";
import { usageFixture } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { encryptToken, decryptToken } from "@/lib/crypto";
import { rotateTokenPage } from "@/lib/token-rotation";
function v1() {
  const iv = Buffer.alloc(12, 1),
    c = createCipheriv("aes-256-gcm", Buffer.from("ab".repeat(32), "hex"), iv);
  const value = Buffer.concat([c.update("fixture"), c.final()]);
  return [
    "v1",
    iv.toString("base64url"),
    c.getAuthTag().toString("base64url"),
    value.toString("base64url"),
  ].join(".");
}
describe.runIf(databaseTestsEnabled)("paged encryption rotation", () => {
  let f: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    f = await usageFixture();
    vi.stubEnv("TOKEN_ENCRYPTION_KEY", "ab".repeat(32));
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "A");
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "cd".repeat(32));
    vi.stubEnv("TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON", "{}");
  });
  afterAll(async () => {
    vi.unstubAllEnvs();
    await f?.close();
  });
  it("has a read-only dry run, resumes mixed v1/A/B owner and retained deletion credentials, and is idempotent", async () => {
    const ids = [randomUUID(), randomUUID(), randomUUID()].sort();
    await f.db.user.createMany({
      data: ids.map((id, i) => ({
        id,
        email: `${id}@example.test`,
        encryptedRefreshToken: i === 0 ? v1() : encryptToken("fixture", id),
      })),
    });
    const deleted = randomUUID();
    await f.db.accountDeletionJob.create({
      data: {
        userId: deleted,
        requestedAt: new Date(),
        credentialExpiresAt: new Date(Date.now() + 86400000),
        encryptedRevocationToken: encryptToken("fixture", deleted),
      },
    });
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "B");
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "ef".repeat(32));
    vi.stubEnv(
      "TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON",
      JSON.stringify({ A: "cd".repeat(32) }),
    );
    await f.db.user.update({
      where: { id: ids[2] },
      data: { encryptedRefreshToken: encryptToken("fixture", ids[2]) },
    });
    const before = await f.db.user.findMany({ orderBy: { id: "asc" } }),
      jobsBefore = await f.db.accountDeletionJob.findMany();
    const dry = await rotateTokenPage();
    expect(dry).toMatchObject({
      scanned: 4,
      eligible: 3,
      current: 1,
      updated: 0,
    });
    expect(await f.db.user.findMany({ orderBy: { id: "asc" } })).toEqual(
      before,
    );
    expect(await f.db.accountDeletionJob.findMany()).toEqual(jobsBefore);
    let after: string | undefined,
      updated = 0;
    do {
      const page = await rotateTokenPage({ apply: true, take: 1, after });
      updated += page.updated;
      after = page.cursor ?? undefined;
    } while (after);
    expect(updated).toBe(3);
    expect(await rotateTokenPage({ apply: true })).toMatchObject({
      current: 4,
      updated: 0,
    });
    for (const user of await f.db.user.findMany())
      expect(decryptToken(user.encryptedRefreshToken!, user.id)).toBe(
        "fixture",
      );
    const job = await f.db.accountDeletionJob.findUniqueOrThrow({
      where: { userId: deleted },
    });
    expect(decryptToken(job.encryptedRevocationToken!, deleted)).toBe(
      "fixture",
    );
  });
  it("CAS does not overwrite a concurrent reconnect or revive erased job credentials", async () => {
    const owner = randomUUID();
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "A");
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "cd".repeat(32));
    vi.stubEnv("TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON", "{}");
    const old = encryptToken("old", owner);
    await f.db.user.create({
      data: {
        id: owner,
        email: `${owner}@example.test`,
        encryptedRefreshToken: old,
      },
    });
    const job = await f.db.accountDeletionJob.create({
      data: {
        userId: owner,
        requestedAt: new Date(),
        credentialExpiresAt: new Date(Date.now() + 86400000),
        encryptedRevocationToken: old,
      },
    });
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "B");
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "ef".repeat(32));
    vi.stubEnv(
      "TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON",
      JSON.stringify({ A: "cd".repeat(32) }),
    );
    const original = f.db.user.updateMany.bind(f.db.user),
      originalJob = f.db.accountDeletionJob.updateMany.bind(
        f.db.accountDeletionJob,
      );
    const fresh = encryptToken("reconnected", owner);
    const spy = vi
      .spyOn(f.db.user, "updateMany")
      .mockImplementationOnce((async (args: Parameters<typeof original>[0]) => {
        await f.db.user.update({
          where: { id: owner },
          data: { encryptedRefreshToken: fresh },
        });
        return original(args);
      }) as unknown as typeof original);
    const jobSpy = vi
      .spyOn(f.db.accountDeletionJob, "updateMany")
      .mockImplementationOnce((async (
        args: Parameters<typeof originalJob>[0],
      ) => {
        await f.db.accountDeletionJob.update({
          where: { id: job.id },
          data: {
            encryptedRevocationToken: null,
            credentialErasedAt: new Date(),
          },
        });
        return originalJob(args);
      }) as unknown as typeof originalJob);
    const result = await rotateTokenPage({ apply: true });
    expect(result.conflicts).toBe(2);
    spy.mockRestore();
    jobSpy.mockRestore();
    expect(
      (await f.db.user.findUniqueOrThrow({ where: { id: owner } }))
        .encryptedRefreshToken,
    ).toBe(fresh);
    expect(
      (
        await f.db.accountDeletionJob.findUniqueOrThrow({
          where: { userId: owner },
        })
      ).encryptedRevocationToken,
    ).toBeNull();
  });
});
